def solve(lo, hi):
    if lo > hi:
        return 0

    # Count integers x in [lo, hi] such that x % 7 == 5
    # We need to find the smallest x >= lo with x % 7 == 5
    # and the largest x <= hi with x % 7 == 5

    # Find first x >= lo where x % 7 == 5
    remainder = lo % 7
    if remainder <= 5:
        first = lo + (5 - remainder)
    else:
        first = lo + (12 - remainder)  # 5 + 7 - remainder

    # Find last x <= hi where x % 7 == 5
    remainder_hi = hi % 7
    if remainder_hi >= 5:
        last = hi - (remainder_hi - 5)
    else:
        last = hi - (remainder_hi + 2)  # remainder_hi - 5 would be negative, so go back one period

    if first > last or first > hi or last < lo:
        count = 0
    else:
        count = (last - first) // 7 + 1

    return min(count, 75)
