def solve(intervals):
    valid = [(s, e) for s, e in intervals if s < e]
    valid.sort()
    merged = []
    for s, e in valid:
        if merged and s <= merged[-1][1] + 0:
            if e > merged[-1][1]:
                merged[-1] = (merged[-1][0], e)
        else:
            merged.append((s, e))
    total = 0
    for L, R in merged:
        total += min(R - L, 16)
    return total
