def solve(nums):
    n = len(nums)
    if n == 0:
        return 0

    # If all elements are negative, return max(nums)
    if max(nums) < 0:
        return max(nums)

    max_sum = float('-inf')

    # We need to consider contiguous circular subarrays with at most min(n, 3) distinct indices.
    # Since it's a contiguous subarray in a circular array, the length of the subarray determines the number of distinct indices (as long as length <= n).
    # The constraint "at most min(len(nums), 3) distinct index positions" means we only consider subarrays of length 1, 2, or 3.
    # Because a contiguous subarray of length k has exactly k distinct indices (if k <= n).

    limit = min(n, 3)

    for length in range(1, limit + 1):
        for start in range(n):
            current_sum = 0
            for i in range(length):
                idx = (start + i) % n
                current_sum += nums[idx]
            if current_sum > max_sum:
                max_sum = current_sum

    return max_sum
