def solve(n, edges):
    if n <= 0:
        return 0

    adj = [[] for _ in range(n)]
    for e in edges:
        u, v, w = e[0], e[1], e[2]
        if 0 <= u < v < n:
            adj[u].append((v, w))

    NEG = float('-inf')
    cur = [[NEG] * n for _ in range(2)]
    cur[0][0] = 0

    for _ in range(3):
        nxt = [row[:] for row in cur]  # allow paths with fewer edges (stay transition)
        for u in range(n):
            for p in (0, 1):
                base = cur[p][u]
                if base == NEG:
                    continue
                for v, w in adj[u]:
                    np = (p + w) % 2
                    val = base + w
                    if val > nxt[np][v]:
                        nxt[np][v] = val
        cur = nxt

    ans = 0
    for v in range(n):
        if cur[0][v] > ans:
            ans = cur[0][v]
    return ans
