def solve(n, edges):
    if n <= 0:
        return 0

    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        if 0 <= u < v < n:
            adj[u].append((v, w))

    dp = {(0, 0): 0}
    answer = 0

    for _ in range(3):
        next_dp = {}
        for (u, remainder), total in dp.items():
            for v, w in adj[u]:
                new_remainder = (remainder + (w % 2)) % 2
                new_total = total + w
                key = (v, new_remainder)
                previous = next_dp.get(key)
                if previous is None or new_total > previous:
                    next_dp[key] = new_total

        dp = next_dp
        for (v, remainder), total in dp.items():
            if remainder == 0 and total > answer:
                answer = total

    return answer
